turbovecAdapter.text:
/**
 * turbovec-prefilter.ts
 * Thin client for the TurboVec ANN sidecar wrapper (:8792) and Python helper (:8793).
 * Wraps /prefilter and /search endpoints with a configurable timeout + graceful fallback.
 */

import { ENV } from '$lib/server/env.server.js';
import { turbovecGrpcSearch, type TurboVecCandidateIdentity } from '$lib/server/grpc/turbovec-cuda-client.js';

export interface TurboVecPrefilterResult {
  clusterIds: number[];
  centroidScores: Record<string, number>;
  backend: 'python' | 'js' | 'offline';
  durationMs: number;
}

export interface TurboVecSearchResult {
  candidates: Array<{
    id: string;
    score: number;
    cluster: number;
    /** Provenance only; absent means this executor result is not promotion-eligible. */
    identity?: TurboVecCandidateIdentity;
  }>;
  backend: 'python' | 'js' | 'offline';
  durationMs: number;
}

const EMPTY_PREFILTER: TurboVecPrefilterResult = {
  clusterIds: [],
  centroidScores: {},
  backend: 'offline',
  durationMs: 0,
};

const EMPTY_SEARCH: TurboVecSearchResult = {
  candidates: [],
  backend: 'offline',
  durationMs: 0,
};

function sidecarUrl(): string {
  return ENV.TURBOVEC_SIDECAR;
}

/**
 * Call /prefilter — returns top cluster IDs for injecting into a Qdrant `must` filter.
 * Times out after `opts.timeoutMs` (default 250ms). Returns empty result on failure.
 */
export async function turbovecPrefilter(
  embedding: Float32Array | number[],
  opts: { topClusters?: number; timeoutMs?: number } = {}
): Promise<TurboVecPrefilterResult> {
  const t0 = Date.now();
  const timeoutMs = opts.timeoutMs ?? 250;
  try {
    const res = await fetch(`${sidecarUrl()}/prefilter`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        vector: Array.from(embedding),
        topClusters: opts.topClusters ?? 5,
      }),
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!res.ok) return EMPTY_PREFILTER;
    const data = await res.json();
    return {
      clusterIds: data.clusterIds ?? [],
      centroidScores: data.centroidScores ?? {},
      backend: data.backend ?? 'js',
      durationMs: Date.now() - t0,
    };
  } catch {
    return { ...EMPTY_PREFILTER, durationMs: Date.now() - t0 };
  }
}

/**
 * Call /search — returns ANN candidate point IDs for score-boosting (not hard filtering).
 * Times out after `opts.timeoutMs` (default 300ms). Returns empty result on failure.
 */
export async function turbovecSearch(
  embedding: Float32Array | number[],
  opts: { topK?: number; timeoutMs?: number } = {}
): Promise<TurboVecSearchResult> {
  const t0 = Date.now();
  const topK = opts.topK ?? 200;

  if (ENV.TURBOVEC_SIDECAR_GRPC_ENABLED) {
    try {
      const grpcResult = await turbovecGrpcSearch(embedding, topK);
      if (grpcResult) {
        return {
          candidates: (grpcResult.candidates ?? []).map(c => ({
            id: c.id,
            score: c.score,
            cluster: c.clusterId,
            ...(c.identity ? { identity: c.identity } : {}),
          })),
          backend: (grpcResult.backend ?? 'grpc') as any,
          durationMs: Date.now() - t0,
        };
      }
    } catch (err) {
      console.warn('[turbovec-prefilter] gRPC search failed, falling back to HTTP:', err);
    }
  }

  const timeoutMs = opts.timeoutMs ?? 300;
  try {
    const res = await fetch(`${sidecarUrl()}/search`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        vector: Array.from(embedding),
        topK,
      }),
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!res.ok) return EMPTY_SEARCH;
    const data = await res.json();
    return {
      candidates: Array.isArray(data.candidates)
        ? data.candidates.map((candidate: Record<string, unknown>) => ({
            id: String(candidate.id ?? ''),
            score: Number(candidate.score ?? 0),
            cluster: Number(candidate.cluster ?? 0),
            ...(candidate.identity && typeof candidate.identity === 'object'
              ? { identity: candidate.identity as TurboVecCandidateIdentity }
              : {}),
          }))
        : [],
      backend: data.backend ?? 'js',
      durationMs: Date.now() - t0,
    };
  } catch {
    return { ...EMPTY_SEARCH, durationMs: Date.now() - t0 };
  }
}

/**
 * Health check — returns sidecar status or null if offline.
 */
export async function turbovecHealth(): Promise<{
  ok: boolean;
  indexed: number;
  dim: number;
  bits: number;
  backend: string;
} | null> {
  try {
    const res = await fetch(`${sidecarUrl()}/health`, {
      signal: AbortSignal.timeout(500),
    });
    if (!res.ok) return null;
    return res.json();
  } catch {
    return null;
  }
}

turbovecGrpcProto.text:
syntax = "proto3";

package turbovec;

// ANN index + optional linear transform. CPU/SIMD, no LibTorch dependency.
service TurboVecService {
  // Liveness + readiness check
  rpc Health (HealthRequest) returns (HealthResponse);

  // ANN top-K search over the quantized vector index
  rpc Search (TurboSearchRequest) returns (TurboSearchResponse);

  // Project vectors through a stored orthogonal transform (768→64 or identity)
  rpc Transform (TransformRequest) returns (TransformResponse);

  // Bulk upsert vectors into the ANN index. Each vector must carry an id string
  // (use Qdrant point UUID or packet_key). Enriched payload metadata (feature_id,
  // community_id, tags) is stored alongside for pre-filter cascade in Search.
  rpc Upsert (UpsertRequest) returns (UpsertResponse);
}

// ── Health ────────────────────────────────────────────────────────────────────

message HealthRequest {}

message HealthResponse {
  bool ok = 1;
  int32 indexed = 2;
  int32 dim = 3;
  int32 bits = 4;
  string backend = 5;
}

// ── Search ────────────────────────────────────────────────────────────────────

message TurboSearchRequest {
  repeated float query_vector = 1;     // 768-dim query
  int32 top_k = 2;
  string transform_id = 3;             // optional: apply stored rotation before scoring
}

message TurboSearchResponse {
  message Candidate {
    string id = 1;
    float score = 2;
    int32 cluster_id = 3;
    // Optional provenance copied from the indexed canonical projection.
    // TurboVec remains a derived ANN executor; these fields do not make it an
    // identity owner.
    CandidateIdentity identity = 4;
  }
  repeated Candidate candidates = 1;
  string backend = 2;
  int32 indexed = 3;
}

message CandidateIdentity {
  string symbol_version_id = 1;
  string packet_key = 2;
  string source_ref = 3;
  string content_hash = 4;
  string source_revision = 5;
  string workspace_revision = 6;
  string namespace = 7;
}

// ── Upsert ────────────────────────────────────────────────────────────────────

message UpsertRecord {
  string id = 1;                  // stable identifier (Qdrant UUID or packet_key)
  repeated float vector = 2;      // 768-dim embedding
  string feature_id = 3;          // optional: enriched payload field
  int32 community_id = 4;         // optional: 0 = not set
  repeated string tags = 5;       // optional: concept_ids / tag labels
}

message UpsertRequest {
  repeated UpsertRecord records = 1;
}

message UpsertResponse {
  int32 indexed = 1;    // total vectors in index after upsert
  int32 inserted = 2;   // new vectors added this call
  int32 updated = 3;    // existing vectors overwritten
  string backend = 4;
}

// ── Transform ─────────────────────────────────────────────────────────────────

message TransformRequest {
  repeated float vectors = 1;     // flattened N x in_dim
  int32 count = 2;                // N
  int32 in_dim = 3;               // input dimension (default 768)
  int32 out_dim = 4;              // output dimension (default 64)
  string transform_id = 5;        // optional: reference a stored orthogonal matrix
}

message TransformResponse {
  repeated float projected_vectors = 1;  // flattened N x out_dim
  int32 count = 2;
  int32 out_dim = 3;
}

turbovecGrpcLegacyProto.text:
syntax = "proto3";

// DEPRECATED — use turbovec.proto (TurboVecService) and gpu_bridge.proto (GpuBridgeService).
// This file is kept for backward compatibility with clients that load turbovec_cuda.proto directly.
// It re-declares both services in their original combined form.
// Do NOT add new RPCs here; add them to the appropriate split proto instead.

package turbovec;

service TurboVecCudaService {
  rpc Health (HealthRequest) returns (HealthResponse);
  rpc Search (TurboSearchRequest) returns (TurboSearchResponse);
  rpc BatchCosine (BatchCosineRequest) returns (BatchCosineResponse);
  rpc EncodeLatent (EncodeLatentRequest) returns (EncodeLatentResponse);
  rpc AssignSom (AssignSomRequest) returns (AssignSomResponse);
  rpc Transform (TransformRequest) returns (TransformResponse);
  rpc Upsert (UpsertRequest) returns (UpsertResponse);
}

// ── Health ────────────────────────────────────────────────────────────────────

message HealthRequest {}

message HealthResponse {
  bool ok = 1;
  int32 indexed = 2;
  int32 dim = 3;
  int32 bits = 4;
  string backend = 5;
}

// ── Search ────────────────────────────────────────────────────────────────────

message TurboSearchRequest {
  repeated float query_vector = 1;
  int32 top_k = 2;
  string transform_id = 3;  // replaces quaternion_rot — reference a stored matrix
}

message TurboSearchResponse {
  message Candidate {
    string id = 1;
    float score = 2;
    int32 cluster_id = 3;
  }
  repeated Candidate candidates = 1;
  string backend = 2;
  int32 indexed = 3;
}

// ── BatchCosine ───────────────────────────────────────────────────────────────

message BatchCosineRequest {
  repeated float query_vector = 1;
  repeated float candidate_vectors = 2;
  int32 candidate_count = 3;
  int32 dim = 4;
}

message BatchCosineResponse {
  repeated float scores = 1;
  int32 count = 2;
}

// ── EncodeLatent ──────────────────────────────────────────────────────────────

message EncodeLatentRequest {
  repeated float vectors = 1;
  int32 count = 2;
  int32 in_dim = 3;
  int32 out_dim = 4;
}

message EncodeLatentResponse {
  repeated float encoded = 1;
  int32 count = 2;
  int32 out_dim = 3;
}

// ── AssignSom ─────────────────────────────────────────────────────────────────

message AssignSomRequest {
  repeated float vectors = 1;
  int32 count = 2;
}

message AssignSomResponse {
  repeated int32 cluster_ids = 1;
  repeated float bmu_scores = 2;
}

// ── Transform ─────────────────────────────────────────────────────────────────

message TransformRequest {
  repeated float vectors = 1;
  int32 count = 2;
  int32 in_dim = 3;
  int32 out_dim = 4;
  string transform_id = 5;
}

message TransformResponse {
  repeated float projected_vectors = 1;
  int32 count = 2;
  int32 out_dim = 3;
}

// ── Upsert ────────────────────────────────────────────────────────────────────

message UpsertRecord {
  string id = 1;
  repeated float vector = 2;
  string feature_id = 3;
  int32 community_id = 4;
  repeated string tags = 5;
}

message UpsertRequest {
  repeated UpsertRecord records = 1;
}

message UpsertResponse {
  int32 indexed = 1;
  int32 inserted = 2;
  int32 updated = 3;
  string backend = 4;
}

turbovecGrpcBridge.text:
#!/usr/bin/env node
/**
 * turbovec-grpc-bridge.mjs
 *
 * Node.js gRPC server on :50062 that implements the TurboVecCudaService
 * contract (proto/active/turbovec_cuda.proto) by composing two existing,
 * already-built pieces:
 *
 *   - simd-bridge/cpp/build/Release/tensorrt_bridge.node  (CUDA / N-API)
 *       → BatchCosine, EncodeLatent, AssignSom, Transform
 *   - Python HTTP sidecar on :8791 (turbovec-sidecar.py)
 *       → Search, Health (indexed count)
 *
 * Hard rules honored (per parent-atlas-open-lanes-todo.md §Hard Rules):
 *   - No re-ingest:        bridge is read-only over what the Python sidecar
 *                          already indexed; Upsert returns indexed=0 / 501.
 *   - No new mutations:    the addon is invoked only for compute (cosine /
 *                          autoencoder / SOM assign), never for writes.
 *   - Fail-open contract:  every method returns a typed-empty response when
 *                          the backing piece is offline, so callers keep
 *                          their existing graceful-fallback logic.
 *
 * Start:
 *   node scripts/sidecars/turbovec-grpc-bridge.mjs                 # :50062
 *   PORT=50062 PYTHON_SIDECAR=http://127.0.0.1:8791 node ...       # override
 *
 * Health probe (after start):
 *   node scripts/atlas/turbovec-grpc-health.mjs
 */

import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const __filename = fileURLToPath(import.meta.url);
const __dirname  = path.dirname(__filename);
const ROOT       = path.resolve(__dirname, '..', '..');

// Resolve @grpc/grpc-js and @grpc/proto-loader from sveltekit-frontend/node_modules
// (root has no package install). Using createRequire keeps the script CWD-agnostic.
const sfRequire = createRequire(path.join(ROOT, 'sveltekit-frontend', 'package.json'));
const grpc        = sfRequire('@grpc/grpc-js');
const protoLoader = sfRequire('@grpc/proto-loader');

const PORT           = Number(process.env.PORT ?? 50062);
const PYTHON_SIDECAR = (process.env.PYTHON_SIDECAR ?? 'http://127.0.0.1:8791').replace(/\/+$/, '');
const ANN_PROTO_PATH = path.join(ROOT, 'proto', 'active', 'turbovec.proto');
const GPU_PROTO_PATH = path.join(ROOT, 'proto', 'active', 'gpu_bridge.proto');
const LEGACY_PROTO_PATH = path.join(ROOT, 'proto', 'active', 'turbovec_cuda.proto');
const ADDON_PATH     = path.join(ROOT, 'simd-bridge', 'cpp', 'build', 'Release', 'tensorrt_bridge.node');

// ── Load N-API addon (optional — bridge stays useful w/o it) ──────────────────

let addon = null;
let addonCudaCode = 0;
try {
  const r = createRequire(import.meta.url);
  addon = r(ADDON_PATH);
  addonCudaCode = addon.checkCudaAvailable?.() ?? 0;
  const label = addonCudaCode === 2 ? 'CUDA+cuDNN' : addonCudaCode === 1 ? 'CUDA' : 'CPU';
  console.log(`[bridge] addon loaded (${label})`);
} catch (err) {
  console.warn(`[bridge] addon NOT loaded: ${err.message.split('\n')[0]}`);
}

// ── Proto load ────────────────────────────────────────────────────────────────

const protoLoaderOptions = {
  keepCase: false,
  longs:    Number,
  enums:    String,
  defaults: true,
  oneofs:   true,
};
const annDescriptor = grpc.loadPackageDefinition(
  protoLoader.loadSync(ANN_PROTO_PATH, protoLoaderOptions)
);
const gpuDescriptor = grpc.loadPackageDefinition(
  protoLoader.loadSync(GPU_PROTO_PATH, protoLoaderOptions)
);
const legacyDescriptor = grpc.loadPackageDefinition(
  protoLoader.loadSync(LEGACY_PROTO_PATH, protoLoaderOptions)
);
const annSvcDef = annDescriptor.turbovec.TurboVecService.service;
const gpuSvcDef = gpuDescriptor.gpubridge.GpuBridgeService.service;
const legacySvcDef = legacyDescriptor.turbovec.TurboVecCudaService.service;

// ── Python sidecar probe (cached, 5s TTL) ─────────────────────────────────────

let pyHealthCache = { at: 0, value: null };

async function probePython() {
  const now = Date.now();
  if (now - pyHealthCache.at < 5000) return pyHealthCache.value;
  try {
    const res = await fetch(`${PYTHON_SIDECAR}/health`, {
      signal: AbortSignal.timeout(1500),
    });
    if (!res.ok) { pyHealthCache = { at: now, value: null }; return null; }
    const j = await res.json();
    pyHealthCache = { at: now, value: j };
    return j;
  } catch {
    pyHealthCache = { at: now, value: null };
    return null;
  }
}

async function pythonSearch(queryVector, topK) {
  try {
    const res = await fetch(`${PYTHON_SIDECAR}/search`, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify({ vector: queryVector, topK }),
      signal:  AbortSignal.timeout(3000),
    });
    if (!res.ok) return null;
    const j = await res.json();
    if (Array.isArray(j.candidates)) return j.candidates;
    if (Array.isArray(j.ids)) {
      const scores = Array.isArray(j.scores) ? j.scores : [];
      return j.ids.map((id, index) => ({
        id,
        score: Number(scores[index] ?? 0),
        cluster: 0,
      }));
    }
    return null;
  } catch {
    return null;
  }
}

// ── Service handlers ──────────────────────────────────────────────────────────

async function health(_call, cb) {
  const py = await probePython();
  cb(null, {
    ok:      Boolean(py?.ok) || addonCudaCode > 0,
    indexed: Number(py?.indexed ?? 0),
    dim:     Number(py?.dim ?? 768),
    bits:    Number(py?.bits ?? py?.bit_width ?? 2),
    backend: py?.ok
      ? `bridge:py(${py.backend ?? 'python'})+addon(${addonCudaCode === 2 ? 'cudnn' : addonCudaCode === 1 ? 'cuda' : 'cpu'})`
      : `bridge:addon(${addonCudaCode === 2 ? 'cudnn' : addonCudaCode === 1 ? 'cuda' : 'cpu'})`,
  });
}

async function search(call, cb) {
  const { queryVector = [], topK = 200 } = call.request ?? {};
  const candidates = await pythonSearch(queryVector, topK);
  if (!candidates) {
    return cb(null, { candidates: [], backend: 'bridge:offline', indexed: 0 });
  }
  const py = await probePython();
  cb(null, {
    candidates: candidates.map((c) => {
      const rawIdentity = c.identity && typeof c.identity === 'object' ? c.identity : null;
      const identity = rawIdentity && Object.values(rawIdentity).some((value) => value != null && value !== '')
        ? {
            symbolVersionId: String(rawIdentity.symbolVersionId ?? rawIdentity.symbol_version_id ?? ''),
            packetKey: String(rawIdentity.packetKey ?? rawIdentity.packet_key ?? ''),
            sourceRef: String(rawIdentity.sourceRef ?? rawIdentity.source_ref ?? ''),
            contentHash: String(rawIdentity.contentHash ?? rawIdentity.content_hash ?? ''),
            sourceRevision: String(rawIdentity.sourceRevision ?? rawIdentity.source_revision ?? ''),
            workspaceRevision: String(rawIdentity.workspaceRevision ?? rawIdentity.workspace_revision ?? ''),
            namespace: String(rawIdentity.namespace ?? ''),
          }
        : undefined;
      return {
        id:        String(c.id ?? ''),
        score:     Number(c.score ?? c.turbovec_score ?? 0),
        clusterId: Number(c.cluster ?? c.cluster_id ?? 0),
        ...(identity ? { identity } : {}),
      };
    }),
    backend: 'bridge:py',
    indexed: Number(py?.indexed ?? 0),
  });
}

function batchCosine(call, cb) {
  const { queryVector = [], candidateVectors = [], candidateCount = 0, dim = 768 } = call.request ?? {};
  if (!addon || typeof addon.batchCosineSimilarity !== 'function') {
    return cb(null, { scores: [], count: 0 });
  }
  try {
    const d = Number(dim) || 768;
    const n = Number(candidateCount) || Math.floor(candidateVectors.length / d);
    const query = toF32(queryVector, d);
    const corpus = toF32(candidateVectors, n * d);
    const scores = new Float32Array(n);
    const rc = addon.batchCosineSimilarity(query, d, corpus, n, scores, n);
    cb(null, { scores: rc === 0 ? Array.from(scores, Number) : [], count: rc === 0 ? scores.length : 0 });
  } catch (err) {
    console.warn('[bridge] batchCosine failed:', err.message);
    cb(null, { scores: [], count: 0 });
  }
}

function encodeLatent(call, cb) {
  const { vectors = [], count = 0, inDim = 768, outDim = 64 } = call.request ?? {};
  if (!addon || typeof addon.autoencoderEncode !== 'function') {
    return cb(null, { encoded: [], count: 0, outDim });
  }
  try {
    const n = Number(count) || Math.floor(vectors.length / Number(inDim || 768)) || 1;
    const inputDim = Number(inDim) || 768;
    const hidden = Number(outDim) || 64;
    const input = toF32(vectors, n * inputDim);
    const { weights, bias } = makeProjectionWeights(inputDim, hidden);
    const res = addon.autoencoderEncode(input, n, inputDim, weights, bias, hidden);
    cb(null, { encoded: Array.from(res ?? [], Number), count: n, outDim: hidden });
  } catch (err) {
    console.warn('[bridge] encodeLatent failed:', err.message);
    cb(null, { encoded: [], count: 0, outDim });
  }
}

function assignSom(call, cb) {
  const { vectors = [], count = 0 } = call.request ?? {};
  if (!addon || typeof addon.somCache !== 'function') {
    return cb(null, { clusterIds: [], bmuScores: [] });
  }
  try {
    // somCache(vectors, count) — current addon returns Float32Array of BMU ids.
    const n = Number(count) || 1;
    const input = toF32(vectors);
    const res = addon.somCache(input, n);
    const clusters = Array.from(res ?? [], Number).slice(0, n);
    cb(null, {
      clusterIds: clusters.map((value) => Math.trunc(value)),
      bmuScores:  clusters.map(() => 1),
    });
  } catch (err) {
    console.warn('[bridge] assignSom failed:', err.message);
    cb(null, { clusterIds: [], bmuScores: [] });
  }
}

function transform(call, cb) {
  // Transform is a PCA / projection op. The addon exports pcaProject; honor the
  // contract shape regardless of which backend ran. Fail-open with empty list.
  const { vectors = [], count = 0, inDim = 768, outDim = 64, transformId = '' } = call.request ?? {};
  if (!addon || typeof addon.pcaProject !== 'function') {
    return cb(null, { projectedVectors: [], count: 0, outDim });
  }
  try {
    const n = Number(count) || Math.floor(vectors.length / Number(inDim || 768)) || 1;
    const inputDim = Number(inDim) || 768;
    const projectedDim = Number(outDim) || 64;
    const input = toF32(vectors, n * inputDim);
    const mean = new Float32Array(inputDim);
    const components = makeProjectionComponents(inputDim, projectedDim);
    const res = addon.pcaProject(input, n, inputDim, mean, components, projectedDim);
    cb(null, { projectedVectors: Array.from(res ?? [], Number), count: n, outDim: projectedDim });
  } catch (err) {
    console.warn('[bridge] transform failed:', err.message);
    cb(null, { projectedVectors: [], count: 0, outDim });
  }
}

function upsert(_call, cb) {
  // Hard rule: no re-ingest from the bridge. Python sidecar owns index state.
  cb(null, { indexed: 0, inserted: 0, updated: 0, backend: 'bridge:read-only' });
}

function toF32(values, expectedLength = 0) {
  const out = new Float32Array(expectedLength || values.length);
  const n = Math.min(out.length, values.length);
  for (let i = 0; i < n; i++) out[i] = Number(values[i]) || 0;
  return out;
}

function makeProjectionComponents(inputDim, outDim) {
  const components = new Float32Array(inputDim * outDim);
  const step = Math.max(1, Math.floor(inputDim / outDim));
  for (let i = 0; i < outDim; i++) {
    components[i * inputDim + Math.min(inputDim - 1, i * step)] = 1;
  }
  return components;
}

function makeProjectionWeights(inputDim, outDim) {
  return {
    weights: makeProjectionComponents(inputDim, outDim),
    bias: new Float32Array(outDim),
  };
}

// ── Server ────────────────────────────────────────────────────────────────────

const server = new grpc.Server({
  'grpc.max_receive_message_length': 32 * 1024 * 1024,
  'grpc.max_send_message_length':    32 * 1024 * 1024,
});

// Canonical split services. ANN provenance is optional derived metadata;
// TurboVec remains an executor, not an identity owner.
server.addService(annSvcDef, {
  health,
  search,
  transform,
  upsert,
});
server.addService(gpuSvcDef, {
  batchCosine,
  encodeLatent,
  assignSom,
});
// Compatibility surface for older clients; do not add new fields or RPCs to
// turbovec_cuda.proto.
server.addService(legacySvcDef, {
  health,
  search,
  batchCosine,
  encodeLatent,
  assignSom,
  transform,
  upsert,
});

server.bindAsync(`0.0.0.0:${PORT}`, grpc.ServerCredentials.createInsecure(), (err, port) => {
  if (err) {
    console.error('[bridge] bind failed:', err.message);
    process.exit(1);
  }
  console.log(`[bridge] TurboVecService + GpuBridgeService listening on 0.0.0.0:${port}`);
  console.log(`[bridge] python sidecar:    ${PYTHON_SIDECAR}`);
  console.log(`[bridge] addon cuda code:   ${addonCudaCode} (0=cpu, 1=cuda, 2=cuda+cudnn)`);
});

function shutdown(sig) {
  console.log(`[bridge] ${sig} → tryShutdown`);
  server.tryShutdown(() => process.exit(0));
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGINT',  () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

turbovecGrpcClient.text:
/**
 * turbovec-cuda-client.ts — gRPC client for TurboVecService (port 50062)
 *
 * ANN index search + optional orthogonal transform. The live :50062 bridge also
 * CUDA-backed tensor ops are exposed separately as GpuBridgeService by the
 * same process. ANN Search depends on the Python/ANN sidecar being loaded
 * from Qdrant; tensor ops can still be healthy when indexed=0.
 *
 * Transport boundary: gRPC = typed high-throughput vector/index calls only.
 * JSON-RPC at :8792 handles agent/tool/debug calls (turbovec-prefilter.ts).
 */
import { ENV } from '$lib/server/env.server.js';
import { buildGrpcClientChannelOptions } from './client-options.js';

// Lazy telemetry: import dynamically to allow graceful fallback if module unavailable
async function tryEmitTelemetry(event: any): Promise<void> {
  try {
    const { emitTelemetry } = await import('$lib/server/telemetry/gpu-telemetry.js');
    await emitTelemetry(event);
  } catch {
    // Telemetry unavailable; continue without it (non-critical)
  }
}

// ── Public types ──────────────────────────────────────────────────────────────

export interface TurboVecHealthResponse {
  ok: boolean;
  indexed: number;
  dim: number;
  bits: number;
  backend: string;
}

export interface TurboVecGrpcCandidate {
  id: string;
  score: number;
  clusterId: number;
  /** Optional provenance copied from the derived ANN index projection. */
  identity?: TurboVecCandidateIdentity;
}

export interface TurboVecCandidateIdentity {
  symbolVersionId?: string | null;
  packetKey?: string | null;
  sourceRef?: string | null;
  contentHash?: string | null;
  sourceRevision?: string | null;
  workspaceRevision?: string | null;
  namespace?: string | null;
}

export interface TurboVecGrpcSearchResponse {
  candidates: TurboVecGrpcCandidate[];
  backend: string;
  indexed: number;
}

export interface TurboVecGrpcTransformResponse {
  projectedVectors: number[];
  count: number;
  outDim: number;
}

export interface TurboVecGrpcUpsertRecord {
  id: string;
  vector: number[] | Float32Array;
  featureId?: string;
  communityId?: number;
  tags?: string[];
}

export interface TurboVecGrpcUpsertResponse {
  indexed: number;
  inserted: number;
  updated: number;
  backend: string;
}

// ── Client singleton ──────────────────────────────────────────────────────────

let _client: any = null;
let _loadFailed = false;
let _retryAt = 0;
let _failLogged = false;

async function getClient(): Promise<any> {
  if (_loadFailed) {
    if (Date.now() < _retryAt) return null;
    _loadFailed = false;
    _client = null;
  }
  if (_client) return _client;

  try {
    const grpc = await import('@grpc/grpc-js');
    const protoLoader = await import('@grpc/proto-loader');
    const { resolve } = await import('path');

    // ANN uses the canonical split proto. GPU tensor methods are owned by the
    // separate gpu-bridge-client and GpuBridgeService contract.
    const PROTO_PATH = resolve(process.cwd(), '../proto/active/turbovec.proto');

    const packageDefinition = await protoLoader.load(PROTO_PATH, {
      keepCase: false,
      longs: Number,
      enums: String,
      defaults: true,
      oneofs: true,
    });

    const descriptor = grpc.loadPackageDefinition(packageDefinition) as Record<string, any>;
    const pkg = descriptor['turbovec'] as Record<string, any>;
    const TurboVecService = pkg['TurboVecService'] as new (
      address: string,
      credentials: any,
      options?: Record<string, any>
    ) => any;

    _client = new TurboVecService(
      ENV.TURBOVEC_SIDECAR_GRPC_URL,
      grpc.credentials.createInsecure(),
      buildGrpcClientChannelOptions({
        maxConnectionIdleMs: 300_000,
        maxSendMessageLength: 32 * 1024 * 1024,
        maxReceiveMessageLength: 32 * 1024 * 1024,
      })
    );

    return _client;
  } catch (err) {
    if (!_failLogged) {
      console.warn(
        '[turbovec-cuda-client] gRPC init failed, will retry in 30s:',
        (err as Error).message
      );
      _failLogged = true;
    }
    _loadFailed = true;
    _retryAt = Date.now() + 30_000;
    return null;
  }
}

function grpcCall<T>(
  client: any,
  method: string,
  req: Record<string, unknown>,
  deadlineMs = 2000
): Promise<T | null> {
  return new Promise((resolve) => {
    client[method](
      req,
      { deadline: Date.now() + deadlineMs },
      (err: Error | null, response: T) => {
        if (err) {
          console.warn(`[turbovec-cuda-client] ${method} error:`, err.message);
          resolve(null);
        } else {
          resolve(response);
        }
      }
    );
  });
}

// ── Exported methods ──────────────────────────────────────────────────────────

export async function turbovecGrpcHealth(): Promise<TurboVecHealthResponse | null> {
  const client = await getClient();
  if (!client) return null;
  return grpcCall<TurboVecHealthResponse>(client, 'health', {}, 3000);
}

export async function turbovecGrpcSearch(
  queryVector: number[] | Float32Array,
  topK = 200,
  transformId = ''
): Promise<TurboVecGrpcSearchResponse | null> {
  const telemetryStart = Date.now();
  const client = await getClient();
  if (!client) {
    await tryEmitTelemetry({
      kernel_name: 'turbovecSearch',
      gpu_backend: 'cpu_fallback',
      operation: 'ann_search',
      candidate_count: topK,
      input_dim: queryVector.length,
      output_dim: topK,
      fallback_used: true,
      error_code: 'grpc_client_unavailable',
      duration_ms: Date.now() - telemetryStart,
      rpc_transport: 'grpc'
    });
    return null;
  }

  const response = await grpcCall<TurboVecGrpcSearchResponse>(
    client,
    'search',
    { queryVector: Array.from(queryVector), topK, transformId },
    2000
  );

  await tryEmitTelemetry({
    kernel_name: 'turbovecSearch',
    gpu_backend: response ? 'simd' : 'cpu_fallback',
    operation: 'ann_search',
    candidate_count: topK,
    input_dim: queryVector.length,
    output_dim: response?.candidates.length ?? topK,
    fallback_used: !response,
    error_code: response ? undefined : 'grpc_call_failed',
    duration_ms: Date.now() - telemetryStart,
    rpc_transport: 'grpc'
  });

  return response;
}

/**
 * Upsert vectors into the live TurboVec sidecar index.
 * NOTE: The gRPC bridge stub is read-only — returns {indexed:0, backend:'bridge:read-only'}.
 * New packets reach TurboVec by being written to Qdrant first; the sidecar rebuilds
 * from Qdrant on next restart. This method is wired for future direct-ingest support.
 */
export async function turbovecGrpcUpsert(
  records: TurboVecGrpcUpsertRecord[],
  deadlineMs = 30_000
): Promise<TurboVecGrpcUpsertResponse | null> {
  const client = await getClient();
  if (!client) return null;
  const payload = records.map((r) => ({
    id: r.id,
    vector: Array.from(r.vector),
    featureId: r.featureId ?? '',
    communityId: r.communityId ?? 0,
    tags: r.tags ?? [],
  }));
  return grpcCall<TurboVecGrpcUpsertResponse>(client, 'upsert', { records: payload }, deadlineMs);
}

export async function turbovecGrpcTransform(
  vectors: number[] | Float32Array,
  count: number,
  inDim = 768,
  outDim = 64,
  transformId = ''
): Promise<TurboVecGrpcTransformResponse | null> {
  const telemetryStart = Date.now();
  const client = await getClient();
  if (!client) {
    await tryEmitTelemetry({
      kernel_name: 'turbovecTransform',
      gpu_backend: 'cpu_fallback',
      operation: 'orthogonal_transform',
      candidate_count: count,
      input_dim: inDim,
      output_dim: outDim,
      fallback_used: true,
      error_code: 'grpc_client_unavailable',
      duration_ms: Date.now() - telemetryStart,
      rpc_transport: 'grpc'
    });
    return null;
  }

  const response = await grpcCall<TurboVecGrpcTransformResponse>(
    client,
    'transform',
    { vectors: Array.from(vectors), count, inDim, outDim, transformId },
    5000
  );

  await tryEmitTelemetry({
    kernel_name: 'turbovecTransform',
    gpu_backend: response ? 'simd' : 'cpu_fallback',
    operation: 'orthogonal_transform',
    candidate_count: count,
    input_dim: inDim,
    output_dim: outDim,
    fallback_used: !response,
    error_code: response ? undefined : 'grpc_call_failed',
    duration_ms: Date.now() - telemetryStart,
    rpc_transport: 'grpc'
  });

  return response;
}

turbovecProofLoader.text:
#!/usr/bin/env node
/**
 * Prove TurboVec ANN + gRPC bridge with real Qdrant vectors.
 *
 * Flow:
 *   Qdrant codebase_chunks_768 -> Python TurboVec /build (:8791)
 *   -> gRPC TurboVecService.Search (:50062)
 *   -> docs/reports/turbovec-ann-grpc-proof.json
 *
 * This is a mirror/accelerator proof. It does not mutate Postgres truth,
 * Qdrant payloads, or packet identity.
 */
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import { loadRepoEnv, REPO_ROOT } from './connection-config.mjs';

const args = new Map();
for (const arg of process.argv.slice(2)) {
  const m = arg.match(/^--([^=]+)=(.*)$/);
  if (m) args.set(m[1], m[2]);
  else if (arg.startsWith('--')) args.set(arg.slice(2), 'true');
}

const env = loadRepoEnv();
const QDRANT_URL = String(args.get('qdrant-url') ?? env.QDRANT_URL ?? 'http://127.0.0.1:6333').replace(/\/+$/, '');
const COLLECTION = String(args.get('collection') ?? env.QDRANT_CODE_COLLECTION ?? 'codebase_chunks_768');
const TURBOVEC_HTTP = String(args.get('turbovec-http') ?? env.TURBOVEC_PYTHON_URL ?? 'http://127.0.0.1:8791').replace(/\/+$/, '');
const GRPC_URL = String(args.get('grpc-url') ?? env.TURBOVEC_SIDECAR_GRPC_URL ?? '127.0.0.1:50062');
const LIMIT = Number(args.get('limit') ?? 1000);
const SCROLL_BATCH = Number(args.get('batch') ?? 128);
const OUT = path.resolve(REPO_ROOT, String(args.get('out') ?? 'docs/reports/turbovec-ann-grpc-proof.json'));
const OUT_MD = path.resolve(REPO_ROOT, String(args.get('out-md') ?? 'docs/reports/turbovec-ann-grpc-proof.md'));

function projectVector(vector, outDim) {
  if (!Array.isArray(vector)) return [];
  if (vector.length === outDim) return vector;
  if (vector.length > outDim) {
    const step = Math.max(1, Math.floor(vector.length / outDim));
    return Array.from({ length: outDim }, (_, index) => Number(vector[Math.min(vector.length - 1, index * step)] ?? 0));
  }
  return [...vector, ...Array(outDim - vector.length).fill(0)];
}

function vectorFromPoint(point) {
  const vector = point.vector;
  if (Array.isArray(vector)) return vector;
  if (vector && typeof vector === 'object') {
    for (const key of ['embeddinggemma_768', 'content', 'default', 'vector']) {
      if (Array.isArray(vector[key])) return vector[key];
    }
    for (const value of Object.values(vector)) {
      if (Array.isArray(value)) return value;
    }
  }
  return null;
}

function identityFromPoint(point) {
  const payload = point.payload ?? {};
  return {
    id: String(point.id),
    packet_key: payload.packet_key ?? payload.packetKey ?? null,
    source_ref: payload.source_ref ?? payload.sourceRef ?? payload.canonical_source_ref ?? payload.canonicalSourceRef ?? payload.file_path ?? null,
    content_hash: payload.content_hash ?? payload.contentHash ?? payload.sha256 ?? null,
    symbol_version_id: payload.symbol_version_id ?? payload.symbolVersionId ?? null,
    source_revision: payload.source_revision ?? payload.sourceRevision ?? null,
    workspace_revision: payload.workspace_revision ?? payload.workspaceRevision ?? null,
    namespace: payload.namespace ?? payload.source_namespace ?? payload.sourceNamespace ?? null,
    feature_id: payload.feature_id ?? payload.featureId ?? null,
    community_id: payload.community_id ?? payload.communityId ?? payload.cluster_id ?? 0,
  };
}

function candidateOk(point) {
  const vector = vectorFromPoint(point);
  const id = identityFromPoint(point);
  return vector?.length === 768 && id.packet_key && id.source_ref && id.feature_id;
}

async function qdrantScroll(offset = null) {
  const body = { limit: SCROLL_BATCH, with_payload: true, with_vector: true };
  if (offset) body.offset = offset;
  const res = await fetch(`${QDRANT_URL}/collections/${COLLECTION}/points/scroll`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(30_000),
  });
  if (!res.ok) throw new Error(`Qdrant scroll HTTP ${res.status}: ${await res.text()}`);
  return (await res.json()).result ?? { points: [], next_page_offset: null };
}

async function collectCandidates(dim = 768) {
  const candidates = [];
  const sampleIdentity = [];
  let scanned = 0;
  let skipped = 0;
  let offset = null;
  while (candidates.length < LIMIT) {
    const { points = [], next_page_offset = null } = await qdrantScroll(offset);
    if (!points.length) break;
    scanned += points.length;
    for (const point of points) {
      if (!candidateOk(point)) {
        skipped += 1;
        continue;
      }
      const vector = vectorFromPoint(point);
      const identity = identityFromPoint(point);
      candidates.push({
        id: identity.packet_key || identity.id,
        vector: projectVector(vector, dim),
        cluster: Number(identity.community_id ?? 0) || 0,
        identity: {
          packetKey: identity.packet_key,
          sourceRef: identity.source_ref,
          contentHash: identity.content_hash,
          symbolVersionId: identity.symbol_version_id,
          sourceRevision: identity.source_revision,
          workspaceRevision: identity.workspace_revision,
          namespace: identity.namespace,
        },
      });
      if (sampleIdentity.length < 5) sampleIdentity.push(identity);
      if (candidates.length >= LIMIT) break;
    }
    if (!next_page_offset) break;
    offset = next_page_offset;
  }
  return { candidates, scanned, skipped, sampleIdentity };
}

async function buildHttpIndex(candidates) {
  const start = Date.now();
  const res = await fetch(`${TURBOVEC_HTTP}/build`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ candidates }),
    signal: AbortSignal.timeout(120_000),
  });
  const text = await res.text();
  let json = {};
  try { json = JSON.parse(text); } catch { json = { raw: text }; }
  if (!res.ok) throw new Error(`TurboVec build HTTP ${res.status}: ${text}`);
  return { ...json, build_request_ms: Date.now() - start };
}

async function httpHealth() {
  const res = await fetch(`${TURBOVEC_HTTP}/health`, { signal: AbortSignal.timeout(5000) });
  if (!res.ok) throw new Error(`TurboVec health HTTP ${res.status}`);
  return res.json();
}

function makeRequire(root) {
  return createRequire(pathToFileURL(path.join(root, '_dummy.js')).href);
}

function loadGrpc() {
  const roots = [
    path.resolve(REPO_ROOT, 'sveltekit-frontend/node_modules'),
    path.resolve(REPO_ROOT, 'node_modules'),
    path.resolve(process.cwd(), 'node_modules'),
  ];
  for (const root of roots) {
    try {
      const req = makeRequire(root);
      return { grpc: req('@grpc/grpc-js'), protoLoader: req('@grpc/proto-loader') };
    } catch {
      // try next
    }
  }
  throw new Error('@grpc/grpc-js not found');
}

function grpcClient() {
  const { grpc, protoLoader } = loadGrpc();
  const protoPath = path.resolve(REPO_ROOT, 'proto/active/turbovec.proto');
  const def = protoLoader.loadSync(protoPath, {
    keepCase: false,
    longs: Number,
    enums: String,
    defaults: true,
    oneofs: true,
  });
  const descriptor = grpc.loadPackageDefinition(def);
  return {
    grpc,
    client: new descriptor.turbovec.TurboVecService(GRPC_URL, grpc.credentials.createInsecure()),
  };
}

function grpcCall(client, method, request, timeoutMs = 10000) {
  return new Promise((resolve, reject) => {
    client[method](request, { deadline: Date.now() + timeoutMs }, (err, response) => {
      if (err) reject(err);
      else resolve(response);
    });
  });
}

async function main() {
  const started = Date.now();
  const report = {
    generated_at: new Date().toISOString(),
    qdrant: { url: QDRANT_URL, collection: COLLECTION },
    turbovec_http: TURBOVEC_HTTP,
    turbovec_grpc: GRPC_URL,
    limit: LIMIT,
    status: 'FAIL',
    gates: {},
  };

  try {
    const before = await httpHealth();
    const sidecarDim = Number(before.dim ?? 768) || 768;
    report.sidecar_dim = sidecarDim;
    const collected = await collectCandidates(sidecarDim);
    report.qdrant.scanned = collected.scanned;
    report.qdrant.skipped = collected.skipped;
    report.qdrant.usable_candidates = collected.candidates.length;
    report.qdrant.sample_identity = collected.sampleIdentity;
    report.gates.qdrant_vectors = collected.candidates.length > 0;

    if (!collected.candidates.length) throw new Error('No usable 768d Qdrant candidates with packet_key/source_ref/feature_id');

    const build = await buildHttpIndex(collected.candidates);
    const after = await httpHealth();
    report.http_health_before = before;
    report.http_build = build;
    report.http_health_after = after;
    report.gates.http_indexed = Number(after.indexed ?? build.indexed ?? 0) > 0;

    const { client } = grpcClient();
    try {
      const grpcHealth = await grpcCall(client, 'health', {}, 5000);
      const queryVector = collected.candidates[0].vector;
      const search = await grpcCall(client, 'search', { queryVector, topK: 10 }, 10000);
      const grpcCandidates = search.candidates ?? [];
      const hasQualifiedIdentity = (candidate) => {
        const identity = candidate?.identity;
        return Boolean(identity
          && identity.packetKey
          && identity.sourceRef
          && identity.contentHash
          && identity.sourceRevision
          && identity.workspaceRevision
          && identity.namespace);
      };
      const identityFields = ['packetKey', 'sourceRef', 'contentHash', 'sourceRevision', 'workspaceRevision', 'namespace'];
      const missingIdentityFields = Object.fromEntries(identityFields.map((field) => [
        field,
        grpcCandidates.filter((candidate) => !String(candidate?.identity?.[field] ?? '').trim()).length,
      ]));
      report.grpc_health = grpcHealth;
      report.grpc_search = {
        backend: search.backend,
        indexed: search.indexed,
        candidates: grpcCandidates.slice(0, 10),
        candidate_count: grpcCandidates.length,
        identity_count: grpcCandidates.filter(hasQualifiedIdentity).length,
        required_identity_fields: identityFields,
        missing_identity_fields: missingIdentityFields,
      };
      report.gates.grpc_ok = Boolean(grpcHealth.ok);
      report.gates.grpc_search_nonempty = grpcCandidates.length > 0;
      report.gates.grpc_identity_preserved = grpcCandidates.length > 0 && grpcCandidates.every(hasQualifiedIdentity);
    } finally {
      client.close();
    }

    report.gates.identity_preserved = collected.sampleIdentity.every((row) => row.packet_key && row.source_ref && row.feature_id);
    report.gates.pass = Object.values(report.gates).every(Boolean);
    // This is an admission precondition, not a best-effort health probe:
    // missing identity/revision metadata must fail closed.
    report.status = report.gates.pass ? 'PASS' : 'FAIL';
  } catch (error) {
    report.error = error.message;
    report.gates.pass = false;
    report.status = 'FAIL';
  }

  report.elapsed_ms = Date.now() - started;
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, JSON.stringify(report, null, 2) + '\n', 'utf8');
  const lines = [
    '# TurboVec ANN gRPC Proof',
    '',
    `Status: ${report.status}`,
    `Qdrant collection: ${COLLECTION}`,
    `Usable candidates: ${report.qdrant?.usable_candidates ?? 0}`,
    `HTTP indexed: ${report.http_health_after?.indexed ?? 0}`,
    `gRPC candidates: ${report.grpc_search?.candidate_count ?? 0}`,
    '',
    '## Gates',
    '',
    '| Gate | Result |',
    '|---|---:|',
    ...Object.entries(report.gates).map(([key, value]) => `| ${key} | ${value ? 'PASS' : 'FAIL'} |`),
  ];
  fs.writeFileSync(OUT_MD, lines.join('\n') + '\n', 'utf8');
  console.log(JSON.stringify({
    status: report.status,
    gates: report.gates,
    qdrant_usable_candidates: report.qdrant?.usable_candidates ?? 0,
    http_indexed: report.http_health_after?.indexed ?? 0,
    grpc_candidates: report.grpc_search?.candidate_count ?? 0,
    out: OUT,
  }, null, 2));
  if (report.status === 'FAIL') process.exit(1);
}

main();

rrfIntegration.text:
/**
 * RRF Integration: Multi-Signal Ranking with Reciprocal Rank Fusion
 *
 * Combines BM25 (lexical), concept overlap, ANN (semantic), and Neo4j (graph)
 * signals via RRF to produce a unified ranked list of context hits.
 *
 * Formula: RRF(d) = Σ weight_i / (k + rank_i(d))
 * Default k=60 keeps early positions dominant while avoiding rank=1 singularity.
 */

import type { Pool } from 'pg';
import type { Redis } from 'ioredis';
import { RETRIEVAL_LIMITS } from './search-contract.js';
import { combineViaRRF, type ContextHit, type RRFResult, type RetrievalLaneName } from './rrf-combiner.js';
import type { DispatcherOrchestrationResult } from '../dispatcher/dispatcher-orchestrator.js';
import { RRF_DEFAULT_WEIGHTS } from './rrf-contract.js';
import { fetchAuthorityScores } from '../search/neo4j-rerank.js';
import {
  resolveEmbeddingLane,
  EmbeddingLaneTelemetryReason,
  emitEmbeddingLaneTelementry,
} from './resolve-embedding-lane.js';
import { resolveCanonicalIdentity, type IdentityResolutionSource } from './identity-resolution.js';

export type { IdentityResolutionSource };

export interface ResolvedCandidateId {
  id: string;
  source: IdentityResolutionSource;
}

/**
 * Resolve a lane hit's canonical dedup identity. Thin adapter over the shared
 * `identity-resolution.ts::resolveCanonicalIdentity` primitive — same precedence
 * (symbol_version_id -> packet_key -> content_hash -> source_ref -> lane-local fallback), just mapped from
 * `ContextHit`'s nested `metadata` shape into the primitive's flat input shape.
 *
 * Without this, combineViaRRF's `deduplicateBy: 'id'` collapses candidates on
 * whatever each lane happened to set as `id` — for the Qdrant lane that's
 * `qdrant_id ?? stable_key ?? file_path`, for BM25/TurboVec it's a lane-local
 * stable key. None of those are the canonical symbol identity, so a symbol
 * with multiple projections (multiple Qdrant points, a BM25 row, a TurboVec
 * candidate) can currently cast more than one independent RRF vote.
 */
export function resolveCanonicalCandidateId(hit: ContextHit): ResolvedCandidateId {
  const metadata = (hit.metadata ?? {}) as Record<string, unknown>;
  const resolved = resolveCanonicalIdentity({
    symbolVersionId: (metadata.symbol_version_id ?? metadata.symbolVersionId) as string | undefined,
    packetKey: (metadata.packet_key ?? metadata.packetKey) as string | undefined,
    contentHash: (metadata.content_hash ?? metadata.contentHash) as string | undefined,
    sourceRef: (metadata.source_ref ?? metadata.sourceRef) as string | undefined,
    fallbackId: hit.id,
  });
  // `resolved.status === 'degraded'` corresponds exactly to `source === 'lane_id_fallback'` —
  // callers here still key off `source` (pre-existing public shape); see
  // CANONICAL_QDRANT_IDENTITY_PAYLOAD for why the fallback tier must stay observable, not silent.
  return { id: resolved.canonicalId, source: resolved.source };
}

/**
 * Rewrite every hit's `id` to its canonical dedup identity before fusion, and record
 * `identity_resolution_source` on every hit so downstream smoke/observability can measure how
 * often fusion is running on real canonical identity versus the degraded lane-id fallback.
 * Lanes that carry no identity metadata (e.g. concept_overlap) still get tagged
 * `lane_id_fallback` even though their `id` is left unchanged — this only tightens dedup where
 * canonical fields are available, it never weakens it, but it never hides the fallback either.
 * The lane-local id is preserved as `raw_lane_id` so per-lane provenance (e.g. which Qdrant
 * point matched) survives even after the RRF-facing id has been normalized.
 */
export function normalizeCanonicalIdentity(hits: ContextHit[]): ContextHit[] {
  return hits.map((hit) => {
    const resolved = resolveCanonicalCandidateId(hit);
    return {
      ...hit,
      id: resolved.id,
      metadata: {
        ...(hit.metadata ?? {}),
        identity_resolution_source: resolved.source,
        ...(resolved.id !== hit.id ? { raw_lane_id: hit.id } : {}),
      },
    };
  });
}

/**
 * TODO: no prior implementation of this function was found anywhere in the
 * repo (grepped repo-wide) — this is a minimal pass-through, not a restored
 * original. It exists so the file type-checks; verify the intended
 * normalization behavior (field stripping? id collision handling?) before
 * relying on its output for ranking-affecting logic.
 */
function normalizeQdrantMetadata(
  record: Record<string, unknown>,
  id: string
): Record<string, unknown> {
  return { ...record, id };
}

function truncateEmbeddingForCollection(
  embedding: number[],
  collection: string
): number[] {
  if (collection === 'codebase_chunks_384_hybrid') {
    if (embedding.length !== 384) {
      throw new Error(
        `384-hybrid collection requires a 384-dim query vector; got ${embedding.length}`
      );
    }
    const norm = Math.sqrt(embedding.reduce((sum, value) => sum + value * value, 0));
    return norm > 0 ? embedding.map((value) => value / norm) : embedding;
  }

  if (collection === 'codebase_chunks_768' && embedding.length !== 768) {
    throw new Error(`768 collection requires a 768-dim query vector; got ${embedding.length}`);
  }

  return embedding;
}

